using HmmLearn;
using HmmLearn.Tests.Support;
using Xunit;

namespace HmmLearn.Tests.Acceptance.Hmm22;

/// <summary>
/// HMM-22: behaviour of the fitted model that the oracle files do not pin down: the monitored variational lower bound
/// must never decrease over the iterations (and must make real progress); fitting only a subset of the emission letters
/// must update exactly that subset; and all four covariance types must agree on data whose true covariance is isotropic.
/// The data is generated by a plain GaussianHmm with a fixed seed, and every fit is seeded (the variational init runs
/// k-means, which is only deterministic with a seeded RandomState).
/// </summary>
public class FitBehaviourTests
{
    private static readonly CovarianceType[] AllTypes =
    {
        CovarianceType.Spherical,
        CovarianceType.Diag,
        CovarianceType.Full,
        CovarianceType.Tied,
    };

    public static IEnumerable<object[]> MonotoneCases()
    {
        foreach (var type in AllTypes)
        foreach (var implementation in new[] { Implementation.Log, Implementation.Scaling })
            yield return new object[] { type, implementation };
    }

    public static IEnumerable<object[]> LetterCases()
    {
        foreach (var @params in new[] { "stc", "stm" })
        foreach (var implementation in new[] { Implementation.Log, Implementation.Scaling })
            yield return new object[] { @params, implementation };
    }

    [Theory]
    [MemberData(nameof(MonotoneCases))]
    public void TheLowerBoundNeverDecreases(CovarianceType covarianceType, Implementation implementation)
    {
        var x = SampleData(300, 1234,
            new double[2, 2, 2] { { { 1, 0.5 }, { 0.5, 1 } }, { { 1, 0.3 }, { 0.3, 1 } } });
        var model = new VariationalGaussianHmm(2, covarianceType, randomState: 42, nIter: 50, implementation: implementation);
        model.Fit(x);

        var history = model.Monitor.History;
        Assert.True(history.Count >= 2, $"expected the fit to run at least two iterations, it ran {history.Count}");
        for (var i = 0; i + 1 < history.Count; i++)
        {
            var tolerance = 1e-6 * Math.Max(1.0, Math.Abs(history[i]));
            Assert.True(history[i + 1] >= history[i] - tolerance,
                $"the lower bound decreased from {history[i]} to {history[i + 1]} between iterations {i} and {i + 1}");
        }
        Assert.True(history[^1] - history[0] > 1e-6,
            $"the lower bound did not increase over the fit: from {history[0]} to {history[^1]}");

        AssertValidFittedModel(model, covarianceType);
    }

    [Fact]
    public void AllCovarianceTypesAgreeOnIsotropicData()
    {
        // The true covariance of both states is 1 * I, so every covariance type is correctly specified and all four
        // fits must land on (nearly) the same parameters.
        var x = SampleData(400, 2024,
            new double[2, 2, 2] { { { 1, 0 }, { 0, 1 } }, { { 1, 0 }, { 0, 1 } } });
        var models = new (CovarianceType Type, VariationalGaussianHmm Model)[]
        {
            (CovarianceType.Spherical, FitFromTheTruth(x, CovarianceType.Spherical)),
            (CovarianceType.Diag, FitFromTheTruth(x, CovarianceType.Diag)),
            (CovarianceType.Full, FitFromTheTruth(x, CovarianceType.Full)),
            (CovarianceType.Tied, FitFromTheTruth(x, CovarianceType.Tied)),
        };

        var reference = models[2].Model;
        foreach (var (type, model) in models)
        {
            if (type == CovarianceType.Full)
                continue;
            Close.Equal(reference.MeansPosterior, model.MeansPosterior, $"means {type} vs full", rtol: 0.05, atol: 0.1);
            Close.Equal(reference.StartProb, model.StartProb, $"startprob {type} vs full", rtol: 0.1, atol: 0.05);
            Close.Equal(reference.TransMat, model.TransMat, $"transmat {type} vs full", rtol: 0.1, atol: 0.05);
            Close.Equal(Variances(reference), Variances(model), $"variances {type} vs full", rtol: 0.1, atol: 0.1);
        }

        // The common result is close to the generating truth.
        Close.Equal(new double[2, 2] { { 0, 0 }, { 5, 5 } }, reference.MeansPosterior, "means vs truth", rtol: 0.0, atol: 0.5);
        Close.Equal(new double[2, 2] { { 1, 1 }, { 1, 1 } }, Variances(reference), "variances vs truth", rtol: 0.5, atol: 0.5);
    }

    [Theory]
    [MemberData(nameof(LetterCases))]
    public void OnlyTheRequestedEmissionParameterChanges(string @params, Implementation implementation)
    {
        var x = SampleData(200, 99,
            new double[2, 2, 2] { { { 1, 0.5 }, { 0.5, 1 } }, { { 1, 0.3 }, { 0.3, 1 } } });
        var model = new VariationalGaussianHmm(2, CovarianceType.Full, randomState: 11, nIter: 10, tol: 1e-12,
            @params: @params, initParams: "", implementation: implementation);

        // Identifiable values: the initial emission parameters are clearly different from the data, so any update is
        // visible.
        var meansPrior = new double[,] { { 1, 2 }, { 3, 4 } };
        var meansPosterior = new double[,] { { 1.5, 2.5 }, { 3.5, 4.5 } };
        var betaPrior = new double[] { 5, 5 };
        var betaPosterior = new double[] { 8, 9 };
        var scalePrior = new double[2, 2, 2] { { { 1, 0 }, { 0, 1 } }, { { 1, 0 }, { 0, 1 } } };
        var scalePosterior = (double[,,])scalePrior.Clone();
        var covars = new double[2, 2, 2] { { { 0.5, 0 }, { 0, 0.5 } }, { { 0.5, 0 }, { 0, 0.5 } } };
        var dofPosterior = new double[] { 6, 6 };
        model.StartProbPriorValues = new double[] { 1, 1 };
        model.StartProbPosterior = new double[] { 3, 5 };
        model.TransMatPriorValues = new double[,] { { 1, 1 }, { 1, 1 } };
        model.TransMatPosterior = new double[,] { { 2, 3 }, { 4, 5 } };
        model.StartProb = new double[] { 0.5, 0.5 };
        model.TransMat = new double[,] { { 0.5, 0.5 }, { 0.5, 0.5 } };
        model.MeansPriorValues = meansPrior;
        model.BetaPriorValues = betaPrior;
        model.MeansPosterior = meansPosterior;
        model.BetaPosterior = betaPosterior;
        model.DofPriorValues = new double[] { 4, 4 };
        model.DofPosterior = dofPosterior;
        model.ScalePriorValues = scalePrior;
        model.ScalePosterior = scalePosterior;
        model.Covars = covars;

        var meansBefore = (double[,])meansPosterior.Clone();
        var betaBefore = (double[])betaPosterior.Clone();
        var dofBefore = (double[])dofPosterior.Clone();
        var scaleBefore = (double[,,])scalePosterior.Clone();
        var covarsBefore = (double[,,])covars.Clone();
        var startPosteriorBefore = (double[])model.StartProbPosterior.Clone();

        model.Fit(x);

        // Both fits include 's' and 't', so both update the start/transition posteriors.
        Changed(startPosteriorBefore, model.StartProbPosterior, "startprob_posterior must change");

        if (@params == "stc")
        {
            Close.Equal(meansBefore, model.MeansPosterior, "means_posterior must stay as it was given");
            Close.Equal(betaBefore, model.BetaPosterior, "beta_posterior must stay as it was given");
            Changed(dofBefore, model.DofPosterior, "dof_posterior must change");
            Changed(scaleBefore, model.ScalePosterior, "scale_posterior must change");
            Changed(covarsBefore, model.Covars, "covars must change");
        }
        else // "stm"
        {
            Close.Equal(dofBefore, model.DofPosterior, "dof_posterior must stay as it was given");
            Close.Equal(scaleBefore, model.ScalePosterior, "scale_posterior must stay as it was given");
            Close.Equal(covarsBefore, model.Covars, "covars must stay as it was given");
            Changed(meansBefore, model.MeansPosterior, "means_posterior must change");
            Changed(betaBefore, model.BetaPosterior, "beta_posterior must change");
        }
    }

    /// <summary>
    /// Data from a plain GaussianHmm: two states with means (0, 0) and (5, 5) and the given per-state covariances.
    /// </summary>
    private static double[,] SampleData(int nSamples, int seed, double[,,] covars)
    {
        var data = new GaussianHmm(2, CovarianceType.Full, initParams: "")
        {
            StartProb = new double[] { 0.7, 0.3 },
            TransMat = new double[,] { { 0.8, 0.2 }, { 0.4, 0.6 } },
            Means = new double[,] { { 0, 0 }, { 5, 5 } },
            Covars = covars,
        };
        var (x, _) = data.Sample(nSamples, random: new Random(seed));
        return x;
    }

    /// <summary>
    /// Fits a variational model from near-truth initial values (weak isotropic prior) with an explicit init.
    /// </summary>
    private static VariationalGaussianHmm FitFromTheTruth(double[,] x, CovarianceType type)
    {
        var model = new VariationalGaussianHmm(2, type, randomState: 7, nIter: 100, tol: 1e-9, initParams: "");
        model.StartProbPriorValues = new double[] { 1, 1 };
        model.StartProbPosterior = new double[] { 50, 50 };
        model.TransMatPriorValues = new double[,] { { 1, 1 }, { 1, 1 } };
        model.TransMatPosterior = new double[,] { { 100, 100 }, { 100, 100 } };
        model.MeansPriorValues = new double[,] { { 0, 0 }, { 5, 5 } };
        model.MeansPosterior = new double[,] { { 0, 0 }, { 5, 5 } };
        model.BetaPriorValues = new double[] { 25, 25 };
        model.BetaPosterior = new double[] { 25, 25 };

        var (dofPrior, scalePrior, covars) = type switch
        {
            CovarianceType.Spherical => (new double[] { 5, 5 },
                                         new double[2, 1, 1] { { { 2.5 } }, { { 2.5 } } },
                                         new double[2, 1, 1] { { { 0.5 } }, { { 0.5 } } }),
            CovarianceType.Diag => (new double[] { 5, 5 },
                                    new double[2, 1, 2] { { { 2.5, 2.5 } }, { { 2.5, 2.5 } } },
                                    new double[2, 1, 2] { { { 0.5, 0.5 } }, { { 0.5, 0.5 } } }),
            CovarianceType.Tied => (new double[] { 10 },
                                    new double[1, 2, 2] { { { 2.5, 0 }, { 0, 2.5 } } },
                                    new double[1, 2, 2] { { { 0.5, 0 }, { 0, 0.5 } } }),
            _ => (new double[] { 5, 5 },
                  new double[2, 2, 2] { { { 2.5, 0 }, { 0, 2.5 } }, { { 2.5, 0 }, { 0, 2.5 } } },
                  new double[2, 2, 2] { { { 0.5, 0 }, { 0, 0.5 } }, { { 0.5, 0 }, { 0, 0.5 } } }),
        };
        model.DofPriorValues = dofPrior;
        model.DofPosterior = (double[])dofPrior.Clone();
        model.ScalePriorValues = scalePrior;
        model.ScalePosterior = (double[,,])scalePrior.Clone();
        model.Covars = covars;

        model.Fit(x);
        return model;
    }

    /// <summary>
    /// The per-state, per-feature variances of a fitted model, regardless of the covariance type.
    /// </summary>
    private static double[,] Variances(VariationalGaussianHmm model)
    {
        var covars = model.Covars!;
        var result = new double[model.NComponents, 2];
        for (var c = 0; c < model.NComponents; c++)
            for (var f = 0; f < 2; f++)
                result[c, f] = model.CovarianceType switch
                {
                    CovarianceType.Spherical => covars[c, 0, 0],
                    CovarianceType.Diag => covars[c, 0, f],
                    CovarianceType.Full => covars[c, f, f],
                    _ => covars[0, f, f],
                };
        return result;
    }

    /// <summary>
    /// A fitted model must be statistically valid: startprob and transmat are probability distributions, the posterior
    /// weights and degrees of freedom are positive, and every variance is finite and positive.
    /// </summary>
    private static void AssertValidFittedModel(VariationalGaussianHmm model, CovarianceType covarianceType)
    {
        var startprob = model.StartProb!;
        var startSum = 0.0;
        for (var i = 0; i < startprob.Length; i++)
        {
            Assert.True(double.IsFinite(startprob[i]), "startprob is not finite");
            Assert.True(startprob[i] >= -1e-12, "startprob is negative");
            startSum += startprob[i];
        }
        Close.Equal(1.0, startSum, "startprob sum");

        var transmat = model.TransMat!;
        for (var i = 0; i < transmat.GetLength(0); i++)
        {
            var rowSum = 0.0;
            for (var j = 0; j < transmat.GetLength(1); j++)
            {
                Assert.True(double.IsFinite(transmat[i, j]), "transmat is not finite");
                Assert.True(transmat[i, j] >= -1e-12, "transmat is negative");
                rowSum += transmat[i, j];
            }
            Close.Equal(1.0, rowSum, $"transmat row {i} sum");
        }

        var means = model.MeansPosterior!;
        for (var c = 0; c < means.GetLength(0); c++)
            for (var f = 0; f < means.GetLength(1); f++)
                Assert.True(double.IsFinite(means[c, f]), "means_posterior is not finite");
        foreach (var beta in model.BetaPosterior!)
            Assert.True(double.IsFinite(beta) && beta > 0, "beta_posterior must be positive");
        foreach (var dof in model.DofPosterior!)
            Assert.True(double.IsFinite(dof) && dof > 0, "dof_posterior must be positive");

        var variances = Variances(model);
        for (var c = 0; c < variances.GetLength(0); c++)
            for (var f = 0; f < variances.GetLength(1); f++)
                Assert.True(double.IsFinite(variances[c, f]) && variances[c, f] > 0,
                    $"variance of state {c}, feature {f} must be positive ({covarianceType})");
    }

    private static void Changed(double[] before, double[] after, string what)
    {
        for (var i = 0; i < before.Length; i++)
            if (Math.Abs(before[i] - after[i]) > 1e-9)
                return;
        Assert.Fail(what);
    }

    private static void Changed(double[,] before, double[,] after, string what)
    {
        for (var i = 0; i < before.GetLength(0); i++)
            for (var j = 0; j < before.GetLength(1); j++)
                if (Math.Abs(before[i, j] - after[i, j]) > 1e-9)
                    return;
        Assert.Fail(what);
    }

    private static void Changed(double[,,] before, double[,,] after, string what)
    {
        for (var i = 0; i < before.GetLength(0); i++)
            for (var j = 0; j < before.GetLength(1); j++)
                for (var k = 0; k < before.GetLength(2); k++)
                    if (Math.Abs(before[i, j, k] - after[i, j, k]) > 1e-9)
                        return;
        Assert.Fail(what);
    }
}
